            "valueString": "None"
          },
          {
            "code": {
              "text": "Leucocytes"
            },
            "valueString": "None"
          },
          {
            "code": {
              "text": "Specific gravity"
            },
            "valueQuantity": {
              "value": 1.003,
              "unit": "1"
            }
          }
        ],
        "valueString": "Dilute urine, noted as consistent with diabetes insipidus."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-20",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-20",
        "status": "final",
        "code": {
          "text": "Cardiovascular examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Heart sounds dual; no murmur."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-21",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-21",
        "status": "final",
        "code": {
          "text": "Chest examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Chest clear."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-22",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-22",
        "status": "final",
        "code": {
          "text": "Neurological examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Alert and oriented to person, place, and time; gait normal; no focal deficit."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-23",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-23",
        "status": "final",
        "code": {
          "text": "Concern about urinary retention"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient is concerned that the bladder is not switching off properly and is worried about urinary retention after being told at hospital to watch for it."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Desmopressin"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "100 micrograms by mouth twice daily at 0800 and 2000; reports taking regularly with no missed doses and no recent dose change.",
            "route": {
              "text": "oral"
            },
            "timing": {
              "repeat": {
                "frequency": 2,
                "period": 1,
                "periodUnit": "d",
                "timeOfDay": [
                  "08:00",
                  "20:00"
                ]
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 100,
                  "unit": "microgram"
                }
              }
            ]
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Desmopressin"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "Continue 100 micrograms by mouth twice daily for now; no dose change until blood results are available and ideally after discussion with usual endocrinologist.",
            "route": {
              "text": "oral"
            },
            "timing": {
              "repeat": {
                "frequency": 2,
                "period": 1,
                "periodUnit": "d",
                "timeOfDay": [
                  "08:00",
                  "20:00"
                ]
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 100,
                  "unit": "microgram"
                }
              }
            ]
          }
        ]
      }
    }
  ]
}

